class TimerComponent extends HTMLElement {
    constructor() {
        super();
        this.attachShadow({ mode: 'open' });
        this.duration = parseInt(this.getAttribute('duration')) || 1500; // Por defecto 25 minutos
        this.interval = null;
        this.remainingTime = this.duration;

        this.shadowRoot.innerHTML = `
            <style>
                .timer-display {
                    font-size: 48px;
                    font-weight: bold;
                    margin-bottom: 10px;
                }
                .controls button {
                    margin: 5px;
                    padding: 10px 15px;
                }
                .message {
                    color: red;
                    display: none;
                }
            </style>
            <div class="timer-display"></div>
            <div class="controls">
                <button id="play">Play</button>
                <button id="pause">Pause</button>
                <button id="reset">Reset</button>
            </div>
            <div id="message" class="message">¡Tiempo Terminado!</div>
        `;
    }

    connectedCallback() {
        this.display = this.shadowRoot.querySelector('.timer-display');
        this.messageEl = this.shadowRoot.getElementById('message');
        this.shadowRoot.getElementById('play').addEventListener('click', () => this.startTimer());
        this.shadowRoot.getElementById('pause').addEventListener('click', () => this.pauseTimer());
        this.shadowRoot.getElementById('reset').addEventListener('click', () => this.resetTimer());
        this.updateDisplay();
    }

    updateDisplay() {
        const minutes = Math.floor(this.remainingTime / 60);
        const seconds = this.remainingTime % 60;
        this.display.textContent = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    }

    startTimer() {
        if (this.interval) return;
        this.messageEl.style.display = 'none';
        this.interval = setInterval(() => {
            if (this.remainingTime > 0) {
                this.remainingTime--;
                this.updateDisplay();
            } else {
                this.pauseTimer();
                this.messageEl.style.display = 'block';
                // Dispara un evento personalizado para que la PWA principal lo escuche
                this.dispatchEvent(new CustomEvent('timer-finished', { bubbles: true, composed: true }));
            }
        }, 1000);
    }

    pauseTimer() {
        clearInterval(this.interval);
        this.interval = null;
    }

    resetTimer(newDuration) {
        this.pauseTimer();
        this.duration = newDuration || this.duration;
        this.remainingTime = this.duration;
        this.updateDisplay();
        this.messageEl.style.display = 'none';
    }
}

customElements.define('timer-component', TimerComponent);
